`timescale 1ns/1ns

// cut_it_in_two: drawn in BitSorter. Gates with a delay are cells of bitsorter_cells.sv.

module cut_it_in_two (
    input logic clk,
    input logic a,
    input logic b,
    output logic out
);
    logic r1_q = 1'b0;
    logic r2_q = 1'b0;
    logic g1_y, g2_y, g3_y, g4_y;
    logic r3_q = 1'b0;
    always_ff @(posedge clk)
        r1_q <= a;
    always_ff @(posedge clk)
        r2_q <= b;
    XOR2 #(.Tpdlh(1), .Tpdhl(1)) g1 (.A(r1_q), .B(r2_q), .Z(g1_y));
    INV #(.Tpdlh(1), .Tpdhl(1)) g2 (.A(g1_y), .Z(g2_y));
    INV #(.Tpdlh(1), .Tpdhl(1)) g3 (.A(g2_y), .Z(g3_y));
    INV #(.Tpdlh(1), .Tpdhl(1)) g4 (.A(g3_y), .Z(g4_y));
    assign out = r3_q;
    always_ff @(posedge clk)
        r3_q <= g4_y;
endmodule
